// Turns the Prism suite line icons (desktop Prism Cam renderer/js/icons.js) into Kotlin path data, so the Android
// app draws exactly the same icons. Run:  node tools/icons-to-kotlin.mjs
// Output: app/src/main/java/com/prism/cam/ui/kit/PrismIconData.kt  (generated — do not edit by hand;
// mobile-only icons live in PrismIcons.kt EXTRA).
import { pathToFileURL, fileURLToPath } from 'node:url';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, '..', '..', 'prism-cam', 'app', 'renderer', 'js', 'icons.js');
const { ICONS } = await import(pathToFileURL(src).href);

const attrs = (s) => Object.fromEntries([...s.matchAll(/([a-zA-Z-]+)="([^"]*)"/g)].map((m) => [m[1], m[2]]));
const n = (v, d = 0) => (v === undefined ? d : parseFloat(v));
const f = (x) => +x.toFixed(3);

function circle(cx, cy, rx, ry) {
  return `M${f(cx - rx)} ${f(cy)}a${f(rx)} ${f(ry)} 0 1 0 ${f(2 * rx)} 0a${f(rx)} ${f(ry)} 0 1 0 ${f(-2 * rx)} 0z`;
}
function rect(x, y, w, h, rx, ry) {
  rx = Math.min(rx, w / 2); ry = Math.min(ry, h / 2);
  if (!rx && !ry) return `M${f(x)} ${f(y)}h${f(w)}v${f(h)}h${f(-w)}z`;
  return `M${f(x + rx)} ${f(y)}h${f(w - 2 * rx)}a${f(rx)} ${f(ry)} 0 0 1 ${f(rx)} ${f(ry)}v${f(h - 2 * ry)}` +
    `a${f(rx)} ${f(ry)} 0 0 1 ${f(-rx)} ${f(ry)}h${f(-(w - 2 * rx))}a${f(rx)} ${f(ry)} 0 0 1 ${f(-rx)} ${f(-ry)}` +
    `v${f(-(h - 2 * ry))}a${f(rx)} ${f(ry)} 0 0 1 ${f(rx)} ${f(-ry)}z`;
}

const out = [];
let skipped = [];
for (const [name, svg] of Object.entries(ICONS)) {
  const inner = svg.replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '');
  const parts = [];
  for (const m of inner.matchAll(/<(path|circle|rect|ellipse|line|polyline|polygon)\b([^>]*?)\/?>/g)) {
    const a = attrs(m[2]);
    const filled = a.fill !== undefined && a.fill !== 'none';
    let d;
    switch (m[1]) {
      case 'path': d = a.d; break;
      case 'circle': d = circle(n(a.cx), n(a.cy), n(a.r), n(a.r)); break;
      case 'ellipse': d = circle(n(a.cx), n(a.cy), n(a.rx), n(a.ry)); break;
      case 'rect': { const rx = n(a.rx, n(a.ry)); d = rect(n(a.x), n(a.y), n(a.width), n(a.height), rx, n(a.ry, rx)); break; }
      case 'line': d = `M${a.x1} ${a.y1}L${a.x2} ${a.y2}`; break;
      case 'polyline': case 'polygon': {
        const p = a.points.trim().split(/[\s,]+/);
        d = 'M' + p.slice(0, 2).join(' ') + 'L' + p.slice(2).join(' ') + (m[1] === 'polygon' ? 'z' : '');
        break;
      }
    }
    if (d) parts.push([d, filled]);
  }
  if (!parts.length) { skipped.push(name); continue; }
  const list = parts.map(([d, fl]) => `P(${JSON.stringify(d)}, ${fl})`).join(', ');
  out.push(`        ${JSON.stringify(name)} to listOf(${list}),`);
}

const kt = `// GENERATED by tools/icons-to-kotlin.mjs from the desktop Prism Cam icon set — do not edit.
package com.prism.cam.ui.kit

internal object PrismIconData {
    class P(val d: String, val filled: Boolean)
    val all: Map<String, List<P>> by lazy { build() }
    private fun build(): Map<String, List<P>> = mapOf(
${out.join('\n')}
    )
}
`;
const dest = join(here, '..', 'app', 'src', 'main', 'java', 'com', 'prism', 'cam', 'ui', 'kit', 'PrismIconData.kt');
writeFileSync(dest, kt);
console.log(`icons: ${out.length} written${skipped.length ? `, skipped ${skipped.join(',')}` : ''} → ${dest}`);
